raise ConversionError(f\"{path}.price_cents\", \"missing required field: price_cents or unit_price_cents\")\n        line_items.append({\n            \"sku\": _required(item, \"sku\", f\"{path}.sku\"),\n            \"quantity\": _integer(quantity, f\"{path}.qty\"),\n            \"unitPriceCents\": _integer(price, f\"{path}.price_cents\"),\n        })\n\n    address_key = \"shipTo\" if \"shipTo\" in payload else \"ship_to\"\n    address = _required(payload, address_key)\n    if not isinstance(address, dict):\n        raise ConversionError(address_key, \"must be an object\")\n    address_result = {}\n    if \"country\" in address:\n        address_result[\"country\"] = address[\"country\"]\n    postal = address.get(\"postal\", address.get(\"postalCode\", address.get(\"postal_code\")))\n    if postal is not None:\n        address_result[\"postalCode\"] = postal\n    else:\n        raise ConversionError(f\"{address_key}.postal\", \"missing required postal field\")\n\n    method = payload.get(\"shipping_method\", payload.get(\"shipping\"))\n    unknown, pii_dropped = _legacy_unknown_fields(payload)\n    metadata = {\"source\": \"legacy-v1\"}\n    if unknown:\n        metadata[\"unknownFields\"] = unknown\n    result = {\n        \"orderId\": order_id,\n        \"buyer\": {\"id\": buyer_id, \"displayName\": display_name},\n        \"lineItems\": line_items,\n        \"shipping\": {\"method\": method or \"standard\", \"address\": address_result},\n        \"metadata\": metadata,\n    }\n    return result, pii_dropped, len(unknown)\n\n\ndef convert_order(payload):\n    \"\"\"Convert a legacy order or validate/copy an already-v2 order.\"\"\"\n    _require_mapping(payload)\n    if \"orderId\" in payload:\n        return _convert_v2(payload)[0]\n    return _convert_legacy(payload)[0]\n\n\ndef convert_many(payloads):\n    \"\"\"Convert all records, collecting errors and writing a conversion audit.\"\"\"\n    converted, errors, warnings = [], [], []\n    pii_dropped_count = unknown_fields_count = 0\n    for index, payload in enumerate(payloads):\n        try:\n            _require_mapping(payload)\n            if \"orderId\" in payload:\n                result, pii, unknown = _convert_v2(payload)\n            else:\n                result, pii, unknown = _convert_legacy(payload)\n            converted.append(result)\n            pii_dropped_count += pii\n            unknown_fields_count += unknown\n        except Exception as exc:\n            path = getattr(exc, \"path\", \"payload\")\n            errors.append({\"index\": index, \"path\": path, \"error\": str(exc)})\n    audit = {\n        \"converted_count\": len(converted),\n        \"error_count\": len(errors),\n        \"warning_count\": len(warnings),\n        \"pii_dropped_count\": pii_dropped_count,\n        \"unknown_fields_count\": unknown_fields_count,\n    }\n    Path(__file__).with_name(\"conversion_audit.json\").write_text(\n        json.dumps(audit, indent=2) + \"\\n\", encoding=\"utf-8\"\n    )\n    return converted, errors, warnings\n\n\ndef summarize_order(v2_payload):\n    return f\"{v2_payload['orderId']}:{len(v2_payload['lineItems'])}\"\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    if len(argv) != 2:\n        raise SystemExit(\"usage: python -m client input.jsonl output.json\")\n    input_path, output_path = map(Path, argv)\n    payloads = []\n    with input_path.open(encoding=\"utf-8\") as stream:\n        for line_number, line in enumerate(stream, 1):\n            if not line.strip():\n                continue\n            try:\n                payloads.append(json.loads(line))\n            except json.JSONDecodeError as exc:\n                payloads.append({\"__invalid_json__\": f\"line {line_number}: {exc}\"})\n    converted, _, _ = convert_many(payloads)\n    Path(output_path).write_text(json.dumps(converted, indent=2) + \"\\n\", encoding=\"utf-8\")\n\n\nif __name__ == \"__main__\":\n    main()\n\n\n"},"isError":false,"timestamp":1788150670772}]}
